<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount,onMounted} from 'vue'
import {getCurrentWindow} from '@tauri-apps/api/window'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {useAuth} from '../stores/auth'
import {useDatabase} from '../stores/database'
import {command,message,desktop} from '../api'
import {date,localDate,isDeleted} from '../format'
import type {Study,Patient,FieldValue,FieldDefinition,FormSnapshot} from '../types'
import catalogData from '../catalog.json'
import {formFields} from '../formSnapshots'
import {reviseForm} from '../formRevisions'
import {editorFields} from '../editor-conditions'
import {renderLegacy,resolveValue} from '../legacy'
import {calculateLegacy,calculationDependencies,calculatedKeys,invalidateCalculations} from '../calculations'
import versionsData from '../legacy-versions.json'
import TemplateLibrary from '../components/TemplateLibrary.vue'
import {appendTemplate,type UserTemplate} from '../userTemplates'
import ProtocolDocument from '../components/ProtocolDocument.vue'
import Attachments from '../components/Attachments.vue'
import StructuredFields from '../components/StructuredFields.vue'
import PageHeading from '../components/PageHeading.vue'
const showLibrary=ref(false),insertTarget=ref('conclusion')
const referenceSelection=ref<{field:FieldDefinition;referenceKey:string;targetKey:string;optionValue?:string}>()
function selectReference(field:FieldDefinition,referenceKey:string,optionValue?:string){referenceSelection.value={field,referenceKey:field.options?.find(o=>o.value===optionValue)?.referenceSection||referenceKey,targetKey:referenceKey,optionValue};showLibrary.value=true}
watch(showLibrary,open=>{if(!open)referenceSelection.value=undefined})
const insertTargets=computed(()=>[{label:'Заключение',value:'conclusion'},{label:'Дополнение и рекомендации',value:'addition'},...(!effectiveForm.value?.editor?.hideDescription?[{label:'Свободное описание',value:'description'}]:[]),...definitions.value.filter(d=>!d.hidden&&(d.kind==='get'||d.kind.includes('TextArea'))).map(d=>({label:d.label,value:d.key}))])
function insertTemplate(entry:UserTemplate,composed?:string){const text=composed??(entry.value||entry.name);if(referenceSelection.value){const {field,targetKey,optionValue}=referenceSelection.value;updateField(targetKey,text);if(optionValue)updateField(field.key,optionValue,'select');success.value='Текст из справочника добавлен. Проверьте протокол и сохраните исследование.';showLibrary.value=false;return;}if(insertTarget.value==='conclusion')conclusion.value=appendTemplate(conclusion.value,text);else if(insertTarget.value==='addition')addition.value=appendTemplate(addition.value,text);else updateField(insertTarget.value,appendTemplate(fields.value[insertTarget.value]?.value||'',text));success.value='Заготовка добавлена. Проверьте текст и сохраните исследование.';showLibrary.value=false}
const versions=versionsData as Record<string,string>
const preservedForm=ref<FormSnapshot>(),sourceId=ref<number>()
const templateVersion=ref('1'),showAllFields=ref(false)
const catalog=catalogData as Record<string,FieldDefinition[]>
const route=useRoute(),router=useRouter(),db=useDatabase(),auth=useAuth()
const record=ref<Study>(),patient=ref<Patient>(),templateId=ref<number>(),doctorId=ref<number>(),studyDate=ref(localDate()),conclusion=ref(''),addition=ref(''),fields=ref<Record<string,FieldValue>>({}),status=ref('draft'),error=ref(''),saving=ref(false),loading=ref(false),snapshot=ref(''),confirmLeave=ref(false),discardAction=ref<null|(()=>void)>(null),success=ref(''),showFields=ref(true)
const previewMode=ref(false),deleteOpen=ref(false)
const removed=computed(()=>isDeleted(record.value?.status||''))
const canManage=computed(()=>Boolean(record.value&&auth.canWrite&&(auth.admin||record.value.doctor_id===auth.user?.doctorId)))
const isArchive=computed(()=>record.value?.origin==='legacy')
const readonly=computed(()=>previewMode.value||removed.value||!auth.canWrite||Boolean(record.value&&!isArchive.value&&auth.user?.role==='doctor'&&record.value.doctor_id!==auth.user.doctorId)),isNew=computed(()=>!route.params.id)
const currentTemplate=computed(()=>db.info?.templates.find(t=>t.id===templateId.value))
const effectiveForm=computed(()=>preservedForm.value||currentTemplate.value?.formSnapshot||reviseForm({code:currentTemplate.value?.formCode||currentTemplate.value?.code.toLowerCase()||'',version:templateVersion.value,configurationRevision:0,definitions:catalog[(currentTemplate.value?.formCode||currentTemplate.value?.code.toLowerCase()||'')+'_'+templateVersion.value]||[]}))
const formCode=computed(()=>effectiveForm.value?.code||currentTemplate.value?.formCode||currentTemplate.value?.code||record.value?.templateCode||'')
const definitions=computed(()=>effectiveForm.value?.definitions||catalog[formCode.value.toLowerCase()+'_'+templateVersion.value]||[])
const additionalDefinitions=computed<FieldDefinition[]>(()=>{const known=new Set(definitions.value.map(d=>d.key));return Object.entries(fields.value).filter(([key])=>key!=='description'&&!key.startsWith('_')&&!known.has(key)).map(([key,value])=>({key,label:key,kind:'get',valueType:value.type}))})
const templateItems=computed(()=>{const items=db.info?.templates.filter(t=>!t.hidden||t.id===record.value?.template_id).map(t=>({label:t.name,value:t.id}))||[];if(record.value&&!items.some(t=>t.value===record.value!.template_id))items.unshift({label:record.value.title||'Вид исследования не указан',value:record.value.template_id});return items})
const selectedDoctorName=computed(()=>record.value&&record.value.doctor_id===doctorId.value?record.value.doctor||'Не указан':db.info?.doctors.find(d=>d.id===doctorId.value)?.name||'Не выбран')
const doctorItems=computed(()=>{const items=db.info?.doctors.map(d=>({label:record.value?.doctor_id===d.id?record.value.doctor||d.name:d.name,value:d.id}))||[];if(record.value&&!items.some(d=>d.value===record.value!.doctor_id))items.unshift({label:record.value.doctor||'Врач не указан',value:record.value.doctor_id});return items})
const rendered=computed(()=>renderLegacy(formCode.value,templateVersion.value,fields.value))
const hasStructuredData=computed(()=>definitions.value.some(d=>Boolean(fields.value[d.key]?.value)))
const useRendered=computed(()=>rendered.value.supported&&!rendered.value.unknownValues.length&&(readonly.value||hasStructuredData.value))
const activeDefinitions=computed(()=>(showAllFields.value?definitions.value:editorFields(formCode.value,templateVersion.value,definitions.value,fields.value,rendered.value.activeFields)).filter(d=>!d.hidden))
const calculationCode=computed(()=>formCode.value.toLowerCase())
const calculationPending=computed(()=>fields.value._calculation_pending?.value==='1')
const canCalculate=computed(()=>['shit','eho_kg','ginekol','brooho'].includes(formCode.value.toLowerCase()))
function recalculate(){try{Object.assign(fields.value,calculateLegacy(formCode.value,fields.value));delete fields.value._calculation_pending;error.value='';success.value='Расчёт выполнен по формулам исходной программы. Проверьте результат перед сохранением.'}catch(e){error.value=message(e)}}
const visibleFields=computed(()=>{
  const byKey=new Map(definitions.value.map(d=>[d.key,d]))
  return Object.entries(fields.value).filter(([key,v])=>!key.startsWith('_')&&v.value).map(([key,v])=>({key,label:byKey.get(key)?.label||key,value:resolveValue(v)}))
})
const loadedStudy=ref(false)
const formState=()=>JSON.stringify([templateId.value,doctorId.value,studyDate.value,conclusion.value,addition.value,fields.value,status.value,templateVersion.value])
const dirty=computed(()=>!readonly.value&&snapshot.value!==''&&formState()!==snapshot.value)
watch(()=>route.fullPath,load,{immediate:true})
async function load(){loadedStudy.value=false;loading.value=true;error.value='';success.value='';snapshot.value='';previewMode.value=false;record.value=undefined;preservedForm.value=undefined;sourceId.value=undefined;patient.value=undefined;fields.value={};conclusion.value='';addition.value='';studyDate.value=localDate();status.value='draft';templateId.value=undefined;doctorId.value=auth.user?.role==='doctor'?auth.user.doctorId||undefined:undefined
 try{if(!db.info)await db.load();if(route.params.id){const s=await command<Study>('study_detail',{id:Number(route.params.id)});record.value=s;preservedForm.value=s.formSnapshot;templateVersion.value=s.legacy_version||'1';templateId.value=s.template_id;doctorId.value=s.doctor_id;studyDate.value=s.date.slice(0,10);conclusion.value=s.conclusion;addition.value=s.addition;fields.value=formFields(s.fields,s.formSnapshot);status.value=s.status;if(s.patient_id){try{const p=await command<{patient:Patient}>('patient_detail',{id:s.patient_id});patient.value=p.patient}catch(e){if(!message(e).includes('Пациент не найден'))throw e}}}else{const p=await command<{patient:Patient}>('patient_detail',{id:Number(route.params.patientId)});patient.value=p.patient}snapshot.value=formState();if(isNew.value&&route.query.from){const source=await command<Study>('study_detail',{id:Number(route.query.from)});if(source.patient_id!==patient.value?.id)throw new Error('Исходное исследование относится к другому пациенту');sourceId.value=source.id;preservedForm.value=source.formSnapshot;templateId.value=source.template_id;templateVersion.value=source.legacy_version||'1';doctorId.value=auth.user?.role==='doctor'?auth.user.doctorId||undefined:source.doctor_id;conclusion.value=source.conclusion;addition.value=source.addition;fields.value=formFields(source.fields,source.formSnapshot);if(calculationDependencies[calculationCode.value]?.some(key=>fields.value[key]?.value))invalidateCalculations(calculationCode.value,fields.value)}loadedStudy.value=Boolean(record.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function updateField(key:string,value:string,type?:string){if(fields.value[key]?.value===value)return;fields.value[key]=formFields({[key]:{value,type:type||fields.value[key]?.type||'text'}},effectiveForm.value)[key];if(calculationDependencies[calculationCode.value]?.includes(key))invalidateCalculations(calculationCode.value,fields.value)}
const confirmTemplate=ref(false),pendingTemplate=ref<number>()
function requestTemplate(value:number){if(value===templateId.value)return;if(Object.entries(fields.value).some(([key,v])=>key!=='description'&&v.value)){pendingTemplate.value=value;confirmTemplate.value=true}else{pendingTemplate.value=value;changeTemplate()}}
function changeTemplate(){preservedForm.value=undefined;sourceId.value=undefined;const description=fields.value.description;fields.value=description?{description}:{};templateId.value=pendingTemplate.value;const code=db.info?.templates.find(t=>t.id===templateId.value)?.code.toLowerCase()||'';templateVersion.value=db.info?.templates.find(t=>t.id===templateId.value)?.version||versions[code]||'1';confirmTemplate.value=false}
let unlistenClose:(()=>void)|undefined
onMounted(async()=>{if(desktop)unlistenClose=await getCurrentWindow().onCloseRequested(event=>{if(dirty.value){event.preventDefault();discardAction.value=()=>{void getCurrentWindow().destroy()};confirmLeave.value=true}})})
onBeforeUnmount(()=>unlistenClose?.())
async function save(nextStatus:string){saving.value=true;error.value='';success.value='';try{const id=await command<number>('save_study',{input:{formRevision:effectiveForm.value?.configurationRevision??null,sourceId:sourceId.value??null,id:record.value?.id??null,revision:record.value?.revision??null,patientId:patient.value?.id??record.value?.patient_id,templateId:templateId.value,doctorId:doctorId.value,date:studyDate.value,conclusion:conclusion.value,addition:addition.value,fields:fields.value,status:nextStatus,templateVersion:templateVersion.value}});snapshot.value=formState();await db.load();if(isNew.value)await router.replace('/studies/'+id);else await load();success.value=nextStatus==='final'?'Исследование завершено и сохранено':'Черновик сохранён'}catch(e){loadedStudy.value=false;error.value=message(e)}finally{saving.value=false}}
async function copy(){const s=record.value;if(s)await router.push('/studies/new/'+s.patient_id+'?from='+s.id)}
let cancelNavigation:(()=>void)|null=null
onBeforeRouteLeave((_to,_from,next)=>{if(!dirty.value){next();return}cancelNavigation=()=>next(false);discardAction.value=()=>{cancelNavigation=null;next()};confirmLeave.value=true})
function cancelLeave(){cancelNavigation?.();cancelNavigation=null;discardAction.value=null;confirmLeave.value=false}
function discard(){snapshot.value=formState();discardAction.value?.();confirmLeave.value=false;discardAction.value=null}
function unload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
const print=()=>{if(loadedStudy.value&&record.value&&!loading.value&&!saving.value&&!removed.value&&!dirty.value)window.print()}
const moreActions=computed(()=>[
 {label:'Обновить документ',icon:'i-lucide-refresh-cw',disabled:dirty.value||loading.value||saving.value,onSelect:()=>load()},
 {label:previewMode.value?'Вернуться к редактированию':'Предпросмотр документа',icon:'i-lucide-eye',disabled:dirty.value||removed.value||!record.value||!loadedStudy.value||(!previewMode.value&&readonly.value),onSelect:()=>{previewMode.value=!previewMode.value}},
 ...(canManage.value?[{label:removed.value?'Восстановить исследование':'Удалить исследование',icon:removed.value?'i-lucide-undo-2':'i-lucide-trash-2',disabled:dirty.value||saving.value,onSelect:()=>{deleteOpen.value=true}}]:[])
])
async function changeDeleted(){if(!record.value)return;saving.value=true;error.value='';try{const removing=!removed.value;await command('set_study_deleted',{id:record.value.id,revision:record.value.revision,deleted:removing});deleteOpen.value=false;await load();await db.load();success.value=removing?'Исследование удалено. Его можно восстановить.':'Исследование восстановлено.'}catch(e){error.value=message(e)}finally{saving.value=false}}

</script>
<template><section class="page-content study-page" :class="{'study-deleted':removed}"><p v-if="dirty||!record||!loadedStudy" class="print-blocked-notice unsaved-print-notice">{{loadedStudy?'Сохраните исследование и откройте предпросмотр перед печатью.':'Документ не готов к печати. Обновите его и проверьте сообщение программы.'}}</p><p v-if="removed" class="print-blocked-notice">Исследование удалено. Печать документа недоступна до восстановления.</p><RouterLink v-if="patient" :to="'/patients/'+patient.id" class="back-link no-print"><UIcon name="i-lucide-arrow-left"/>К карточке пациента</RouterLink><PageHeading :title="previewMode?'Предпросмотр исследования':readonly?'Просмотр исследования':isNew?'Новое исследование':'Редактирование исследования'" :description="patient?.name||record?.patientName"><template v-if="readonly"><UButton v-if="previewMode" variant="outline" color="neutral" icon="i-lucide-pencil" @click="previewMode=false">Вернуться к редактированию</UButton><UButton color="neutral" variant="outline" icon="i-lucide-copy-plus" @click="copy" :disabled="!desktop||!auth.canWrite||!patient">Создать на основе</UButton><UButton icon="i-lucide-printer" :disabled="removed||loading||saving||!loadedStudy" @click="print">Печать</UButton></template><template v-else><UBadge v-if="dirty" color="warning" variant="subtle" class="dirty-indicator" role="status">Есть изменения</UBadge><UButton color="neutral" variant="outline" :disabled="saving||!desktop||!auth.canWrite||loading" :loading="saving" @click="save('draft')">Сохранить черновик</UButton><UButton icon="i-lucide-check" :disabled="saving||!desktop||!auth.canWrite||loading" @click="save('final')">Завершить</UButton></template><UDropdownMenu v-if="record" :items="moreActions"><UButton color="neutral" variant="outline" icon="i-lucide-ellipsis" :disabled="loading||saving">Ещё</UButton></UDropdownMenu></PageHeading>
<UAlert v-if="removed" color="warning" title="Исследование удалено" description="Документ сохранён для просмотра. Чтобы редактировать или распечатать его, восстановите запись. Исходные архивные удаления восстанавливаются как черновики." class="mb-5 no-print"/><UAlert v-if="calculationPending" color="warning" variant="soft" title="Расчёт не выполнен" description="Размеры изменились, прежние вычисленные значения удалены. Можно завершить и распечатать исследование без расчёта. Для расчёта заполните необходимые размеры и нажмите «Пересчитать»." class="mb-5 no-print"/><UAlert v-if="error" color="error" :description="error" class="mb-5 no-print"/><UAlert v-if="rendered.unknownValues.length" color="warning" title="Часть значений отсутствует в исходном справочнике" description="Показаны сохранённые параметры. Печатный текст для этой записи требует проверки." class="mb-5 no-print"/><UAlert v-if="!rendered.supported&&(currentTemplate||readonly)" color="warning" title="Для этой версии шаблона доступны сохранённые параметры" description="Точное формирование связного текста пока не поддерживается." class="mb-5 no-print"/><UAlert v-if="success" color="success" variant="soft" :description="success" class="mb-5 no-print"/>
<div v-if="loading" class="loading-state">Открываем исследование…</div><template v-else-if="patient||record||readonly">
<div class="study-layout" :class="{'readonly-layout':readonly}">
<aside v-if="!readonly" class="study-settings no-print" aria-labelledby="study-settings-title">
  <h2 id="study-settings-title">Об исследовании</h2>
  <div class="study-settings-fields">
    <UFormField label="Вид исследования" required><USelect :model-value="templateId" :items="templateItems" placeholder="Выберите исследование" class="w-full" @update:model-value="requestTemplate"/></UFormField>
    <UFormField label="Врач" required><USelect :disabled="auth.user?.role==='doctor'&&!isArchive" v-model="doctorId" :items="doctorItems" placeholder="Выберите врача" class="w-full"/></UFormField>
    <UFormField label="Дата исследования" required><UInput v-model="studyDate" type="date" class="w-full"/></UFormField>
  </div>
  <UButton icon="i-lucide-book-open" variant="outline" class="study-template-button" @click="showLibrary=true">Справочник шаблонов</UButton>
</aside>
<ProtocolDocument v-if="readonly&&record&&loadedStudy" :study="record"/><template v-else><ProtocolDocument v-if="record&&!dirty&&loadedStudy" :study="record" class="print-only saved-print-document"/><article class="document-sheet editor-document"><div class="document-header"><span class="document-brand"><UIcon name="i-lucide-activity"/>Протокол исследования</span><span>{{date(studyDate)}}<template v-if="record"> · № {{record.id}}</template></span></div><h2>{{(record?.template_id===templateId?record?.title:undefined)||currentTemplate?.name||'Выберите вид исследования'}}</h2><dl class="document-patient"><div><dt>Пациент</dt><dd>{{patient?.name||record?.patientName||'Без карточки пациента'}}</dd></div><div><dt>Дата рождения</dt><dd>{{date(patient?.birthdate||record?.patientBirthdate)}}</dd></div><div><dt>Врач</dt><dd>{{selectedDoctorName}}</dd></div></dl>
<p v-if="calculationCode==='shit'" class="print-unit-note">В исходном шаблоне объём обозначен как «мм». Обозначения сохранены для сопоставления с архивом. При размерах в миллиметрах исходная формула рассчитывает объём в см³.</p>
<p v-if="record?.status==='draft'||record?.status==='legacy:0'" class="print-unit-note">ЧЕРНОВИК. Исследование не завершено.</p><p v-if="calculationPending" class="print-unit-note">Вычисленные значения удалены после изменения размеров. Расчёт не выполнен.</p>
<template v-if="readonly"><section v-if="useRendered" class="document-section legacy-protocol" v-html="rendered.html"></section><section v-else-if="visibleFields.length" class="document-section"><h3>Сохранённые параметры исследования</h3><dl class="archive-fields"><div v-for="field in visibleFields" :key="field.key"><dt>{{field.label}}</dt><dd>{{field.value}}</dd></div></dl></section><section class="document-section"><h3>Заключение</h3><p class="preserve-lines">{{conclusion||'Заключение не заполнено'}}</p></section><section v-if="addition" class="document-section"><h3>Дополнение</h3><p class="preserve-lines">{{addition}}</p></section><p v-if="isArchive" class="archive-print-note">{{rendered.supported&&!rendered.unknownValues.length?'Архивная запись. Содержание сформировано по исходному шаблону; оформление адаптировано для A4.':'Архивная запись. Показаны сохранённые параметры; связный текст для этой версии требует проверки.'}}</p></template>
<template v-else><section v-if="!effectiveForm?.editor?.hideDescription" class="document-section no-print"><h3>Описание исследования</h3><UFormField label="Протокол" description="Свободное описание результатов исследования"><UTextarea :model-value="fields.description?.value||''" @update:model-value="updateField('description',$event)" :rows="8" autoresize class="w-full" placeholder="Опишите результаты исследования…"/></UFormField></section><section v-if="definitions.length" class="document-section no-print"><button class="field-toggle" @click="showFields=!showFields" :aria-expanded="showFields"><UIcon :name="showFields?'i-lucide-chevron-down':'i-lucide-chevron-right'"/>Поля исходного шаблона <span>{{definitions.filter(d=>!d.hidden).length}}</span></button><template v-if="showFields"><div class="flex items-center justify-between gap-4 flex-wrap mb-5"><UCheckbox v-model="showAllFields" label="Показать все поля шаблона"/><UButton v-if="canCalculate" icon="i-lucide-calculator" variant="outline" @click="recalculate">Пересчитать</UButton></div><p v-if="canCalculate" class="calculation-units">{{calculationCode==='eho_kg'?'Размеры для расчёта — в см.':'Размеры для расчёта — в мм.'}}</p><StructuredFields :readonly-keys="calculatedKeys[calculationCode]||[]" :definitions="activeDefinitions" :fields="fields" @change="updateField" @reference="selectReference"/><section v-if="useRendered" class="document-section"><h3>Предпросмотр протокола</h3><div class="legacy-protocol" v-html="rendered.html"></div></section></template></section><section v-if="additionalDefinitions.length" class="document-section no-print"><h3>Сохранённые параметры</h3><StructuredFields :definitions="additionalDefinitions" :fields="fields" @change="updateField" @reference="selectReference"/></section><section class="document-section no-print"><UFormField label="Заключение" required><UTextarea v-model="conclusion" :rows="5" autoresize class="w-full" placeholder="Введите заключение…"/></UFormField></section><section class="document-section no-print"><UFormField label="Дополнение и рекомендации"><UTextarea v-model="addition" :rows="3" autoresize class="w-full" placeholder="При необходимости"/></UFormField></section><div v-if="record" class="flex justify-end no-print"><UButton variant="ghost" color="neutral" icon="i-lucide-printer" @click="print" :disabled="dirty||loading||saving||!loadedStudy">Печать сохранённой записи</UButton></div></template>
<footer class="document-signature"><span>Врач: {{selectedDoctorName}}</span><span>Подпись __________________</span></footer>
</article></template></div><Attachments v-if="record" :study-id="record.id" :editable="!readonly&&auth.canWrite&&desktop"/></template>
<UModal v-model:open="deleteOpen" :dismissible="!saving" :title="removed?'Восстановить исследование?':'Удалить исследование?'" :description="removed?'Запись вернётся в историю. Если прежний статус архива неизвестен, она станет черновиком.':'Документ и вложения сохранятся. Запись можно восстановить; комплекты с ней потребуют проверки.'"><template #body><UAlert v-if="error" color="error" :description="error"/></template><template #footer><UButton color="neutral" variant="outline" :disabled="saving" @click="deleteOpen=false">Отмена</UButton><UButton :color="removed?'primary':'error'" :loading="saving" :disabled="saving" @click="changeDeleted">{{removed?'Восстановить':'Удалить'}}</UButton></template></UModal>
<UModal v-model:open="showLibrary" title="Справочник шаблонов" :description="referenceSelection?'Выберите заготовку для поля. Она заменит выбранный ранее текст.':'Выберите, куда добавить заготовку. Уже введённый текст сохранится.'" :ui="{content:'sm:max-w-3xl'}"><template #body><UFormField v-if="!referenceSelection" label="Куда вставить" class="mb-5"><USelect v-model="insertTarget" :items="insertTargets" class="w-full"/></UFormField><p v-if="referenceSelection" class="mb-4">{{referenceSelection.field.group}} · {{referenceSelection.field.label}}</p><TemplateLibrary v-if="showLibrary" :template-id="templateId" :reference-key="referenceSelection?.referenceKey" pick @select="insertTemplate"/></template></UModal>
<UModal v-model:open="confirmTemplate" title="Сменить вид исследования?" description="Заполненные поля прежнего шаблона будут удалены. Свободное описание, заключение и рекомендации сохранятся."><template #footer><UButton color="neutral" variant="outline" @click="confirmTemplate=false">Оставить прежний вид</UButton><UButton color="warning" @click="changeTemplate">Сменить и очистить поля</UButton></template></UModal>
<UModal :open="confirmLeave" @update:open="cancelLeave" title="Остались несохранённые изменения" description="Сохраните исследование или выйдите без сохранения."><template #footer><UButton color="neutral" variant="outline" @click="cancelLeave">Продолжить редактирование</UButton><UButton color="error" @click="discard">Выйти без сохранения</UButton></template></UModal>
</section></template>

